class Estoque:
    def __init__(self):
        self.itens = {}

    def adicionar(self, nome, qtd):
        self.itens[nome] = self.itens.get(nome, 0) + qtd

    def total(self):
        return sum(v for v in self.itens.values() if v > 0)

